<!DOCTYPE html><html lang="de"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aufträge-Wiedervorlage</title><style>*{box-sizing:border-box}body{margin:0;font:14px Segoe UI,Arial;background:#f4f6f8;color:#1f2937}.page{max-width:1400px;margin:auto;padding:28px}.card{background:#fff;border-radius:12px;box-shadow:0 2px 8px #0001;padding:22px}.filters{display:flex;gap:8px;flex-wrap:wrap}input,select,button{padding:9px;border:1px solid #cbd5e1;border-radius:6px}table{width:100%;border-collapse:collapse;margin-top:16px}th,td{padding:10px 8px;border-bottom:1px solid #e5e7eb;text-align:left;vertical-align:top}.due{background:#fff7ed}a{color:#0369a1;text-decoration:none}</style></head><body><div class="page"><div style="text-align:right"><a href="{{ route('frontend.switch','classic') }}">← Zur klassischen Ansicht</a></div><h1>Aufträge-Wiedervorlage</h1><div class="card"><form class="filters" method="get"><input name="q" value="{{ request('q') }}" placeholder="Kunde, Auftrag, Position, Text"><select name="status"><option value="due" @selected($status==='due')>Fällig</option><option value="future" @selected($status==='future')>Zukünftig</option><option value="all" @selected($status==='all')>Alle</option></select><button>Filtern</button></form>@if($positionen->isEmpty())<p>Keine Wiedervorlagen gefunden.</p>@else<table><thead><tr><th>Datum</th><th>Kunde</th><th>Auftrag</th><th>Position</th><th>Beschreibung</th><th>Notiz</th><th>Mindestlaufzeit</th></tr></thead><tbody>@foreach($positionen as $p)<tr @class(['due'=>strtotime($p->datWiedervorlageVertrieb)<=time()])><td>{{ date('d.m.Y',strtotime($p->datWiedervorlageVertrieb)) }}</td><td>{{ $kunden[$p->intKID]->strName ?? ('#'.$p->intKID) }}</td><td><a href="{{ route('kunden.auftraege.show',[$p->intKID,$p->intAufNr]) }}">{{ $p->intAufNr }}</a></td><td><a href="{{ route('kunden.auftraege.positionen.edit',[$p->intKID,$p->intAufNr,$p->intID]) }}">{{ $p->intID }}</a></td><td>{{ $p->strBeschreibung }}</td><td>{{ $p->txtWiedervorlageVertrieb }}</td><td>{{ $p->datMindeslaufzeitEnde ? date('d.m.Y',strtotime($p->datMindeslaufzeitEnde)) : '' }}</td></tr>@endforeach</tbody></table>{{ $positionen->links() }}@endif</div></div><script src="{{ asset('js/db-window-manager.js') }}"></script></body></html>